CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, member_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, full_name text NOT NULL DEFAULT '' CHECK (length(full_name)<=100), email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), photo text NOT NULL DEFAULT '', account_type text NOT NULL DEFAULT 'client' CHECK(account_type IN ('client','owner','staff')));
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_ironhaus_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email,phone,account_type) VALUES(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),100),coalesce(new.email,''),left(coalesce(new.raw_user_meta_data->>'phone',''),30),CASE WHEN new.raw_user_meta_data->>'account_type' IN ('owner','staff') THEN new.raw_user_meta_data->>'account_type' ELSE 'client' END); RETURN new; END $$;
CREATE TRIGGER ironhaus_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_ironhaus_profile();
CREATE TABLE public.gyms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), owner_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.gyms TO authenticated; GRANT ALL ON public.gyms TO service_role;
ALTER TABLE public.gyms ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, gym_id uuid REFERENCES public.gyms(id), role text NOT NULL CHECK(role IN ('super_admin','Owner','Admin','Reception','Trainer','Client')), permissions text[] NOT NULL DEFAULT '{}', UNIQUE(user_id,gym_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.otp_verified() RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) x WHERE x->>'method' IN ('otp','totp','phone')) OR auth.jwt()->>'aal'='aal2' $$;
CREATE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='super_admin') $$;
CREATE FUNCTION public.gym_access(g uuid, area text DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=g AND (area IS NULL OR role='Owner' OR (role!='Client' AND area=ANY(permissions)))) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.gym_access(gym_id,'Settings') OR public.is_super_admin());
CREATE POLICY gym_read ON public.gyms FOR SELECT TO authenticated USING(public.gym_access(id) OR public.is_super_admin());
CREATE TABLE public.gym_records(gym_id uuid NOT NULL REFERENCES public.gyms(id), kind text NOT NULL CHECK(kind IN ('gym','members','products','trainers','plans','workouts','sessions','attendance','staffAttendance','recurring','transactions')), id text NOT NULL CHECK(length(id)<=100), data jsonb NOT NULL CHECK(pg_column_size(data)<1048576), client_id uuid REFERENCES public.profiles(id), created_by uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(gym_id,kind,id));
GRANT SELECT ON public.gym_records TO authenticated; GRANT ALL ON public.gym_records TO service_role;
ALTER TABLE public.gym_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY gym_record_read ON public.gym_records FOR SELECT TO authenticated USING(public.gym_access(gym_id,CASE kind WHEN 'members' THEN 'Members' WHEN 'plans' THEN 'Members' WHEN 'sessions' THEN 'Sessions' WHEN 'attendance' THEN 'Attendance' WHEN 'staffAttendance' THEN 'Attendance' WHEN 'workouts' THEN 'Workout programs' WHEN 'gym' THEN 'Settings' ELSE 'Finance' END) OR (public.otp_verified() AND client_id=auth.uid()) OR (kind IN ('gym','workouts') AND public.gym_access(gym_id)));
CREATE TABLE public.client_programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), definition jsonb NOT NULL CHECK(pg_column_size(definition)<1048576), completion integer[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.client_programs TO authenticated; GRANT ALL ON public.client_programs TO service_role;
ALTER TABLE public.client_programs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_programs ON public.client_programs FOR ALL TO authenticated USING(user_id=auth.uid() AND public.otp_verified()) WITH CHECK(user_id=auth.uid() AND public.otp_verified());
CREATE TABLE public.staff_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES public.gyms(id), full_name text NOT NULL CHECK(length(full_name) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email)<=255), role text NOT NULL CHECK(role IN ('Admin','Reception','Trainer')), permissions text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Accepted','Declined','Cancelled')), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now(), accepted_by uuid REFERENCES public.profiles(id));
GRANT SELECT ON public.staff_invitations TO authenticated; GRANT ALL ON public.staff_invitations TO service_role;
ALTER TABLE public.staff_invitations ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX invitation_one_pending ON public.staff_invitations(gym_id,lower(email)) WHERE status='Pending';
CREATE POLICY invitations_read ON public.staff_invitations FOR SELECT TO authenticated USING(public.gym_access(gym_id,'Settings') OR (public.otp_verified() AND lower(email)=lower(auth.jwt()->>'email')));
CREATE TABLE public.owner_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) UNIQUE, gym_name text NOT NULL CHECK(length(gym_name) BETWEEN 1 AND 100), plan text NOT NULL CHECK(plan IN ('Monthly Plan','3 Months Plan','Annual Plan')), status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')), decision_by uuid REFERENCES public.profiles(id), decided_at timestamptz, gym_id uuid REFERENCES public.gyms(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.owner_requests TO authenticated; GRANT ALL ON public.owner_requests TO service_role;
ALTER TABLE public.owner_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_read ON public.owner_requests FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.otp_verified()) OR public.is_super_admin());
CREATE FUNCTION public.respond_invitation(invitation_id uuid, accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.staff_invitations; BEGIN IF NOT public.otp_verified() THEN RAISE EXCEPTION 'OTP verification required'; END IF; SELECT * INTO i FROM public.staff_invitations WHERE id=invitation_id FOR UPDATE; IF i.id IS NULL OR i.status!='Pending' OR i.expires_at<=now() OR lower(i.email)!=lower(auth.jwt()->>'email') THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; IF accept THEN INSERT INTO public.user_roles(user_id,gym_id,role,permissions) VALUES(auth.uid(),i.gym_id,i.role,i.permissions) ON CONFLICT(user_id,gym_id) DO NOTHING; END IF; UPDATE public.staff_invitations SET status=CASE WHEN accept THEN 'Accepted' ELSE 'Declined' END, accepted_by=auth.uid() WHERE id=i.id; END $$;
REVOKE ALL ON FUNCTION public.respond_invitation(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_invitation(uuid,boolean) TO authenticated;
CREATE FUNCTION public.decide_owner_request(request_id uuid, approve boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_requests; g uuid; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO r FROM public.owner_requests WHERE id=request_id FOR UPDATE; IF r.id IS NULL OR r.status!='Pending' THEN RAISE EXCEPTION 'Request unavailable'; END IF; IF approve THEN INSERT INTO public.gyms(name,owner_id) VALUES(r.gym_name,r.user_id) RETURNING id INTO g; INSERT INTO public.user_roles(user_id,gym_id,role,permissions) VALUES(r.user_id,g,'Owner',ARRAY['Members','Attendance','Sessions','Payments','Finance','Workout programs','Settings']); END IF; UPDATE public.owner_requests SET status=CASE WHEN approve THEN 'Approved' ELSE 'Rejected' END,decision_by=auth.uid(),decided_at=now(),gym_id=g WHERE id=r.id; RETURN g; END $$;
REVOKE ALL ON FUNCTION public.decide_owner_request(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.decide_owner_request(uuid,boolean) TO authenticated;